  "Als PDF speichern / Drucken":"Enregistrer en PDF / Imprimer", "STATUSBERICHT PRE-OPENING":"RAPPORT D'AVANCEMENT PRÉ-OUVERTURE", "Stand:":"État au :", "Eröffnung:":"Ouverture :",
