  "Die Online-Bezahlung wird gerade eingerichtet.":"オンライン決済は現在準備中です。",
  "Für ein Abo schreib an":"サブスクリプションのお問い合わせ先：",
  "pro Monat zzgl. USt., monatlich kündbar":"月額（税別）、毎月解約可能",
  "Bald verfügbar":"近日公開",
