  "In den nächsten acht Wochen sind für dich keine Schichten eingetragen.":"今後8週間に予定されているシフトはありません。",
  "Keine Abteilung":"部門なし",
  "Krank":"病欠",
  "KW":"週",
  "Meine Anträge":"自分の申請",
  "Meine Schicht":"自分のシフト",
  "Meine Schichten":"マイシフト",
  "Mindestbesetzung":"最低配置人数",
  "Mitarbeitende":"スタッフ",
