  "Name ohne Login (z. B. Aushilfe)":"ログインなしの名前（例：臨時スタッフ）",
  "Noch niemand in dieser Abteilung. Ordne unter „Team“ Mitarbeitende zu oder trage unten einen Namen ein.":"この部門にはまだ誰もいません。「チーム」でスタッフを割り当てるか、下に名前を入力してください。",
  "Nächste Woche":"翌週",
