  "Von":"開始日",
  "Vorwoche übernehmen":"前週をコピー",
  "Wie viele Personen braucht diese Abteilung je Schicht? Fehlen welche, warnt der Plan.":"この部門ではシフトごとに何人必要ですか？不足すると勤務表が警告します。",
  "Zeile hinzufügen":"行を追加",
  "Zurückziehen":"取り下げる",
  "Zwischen":"中番",
  "ohne Login":"ログインなし",
